  let name = if user.has_suffix("$") {
    user[:user.length() - 1].to_owned()
  } else {
    user
  }
  name != "" &&
  user.length() <= 64 &&
  (
    (name[0] >= 'a' && name[0] <= 'z') ||
    (name[0] >= 'A' && name[0] <= 'Z') ||
    name[0] == '_'
  ) &&
  name
  .to_array()
  .iter()
  .all(c => {
    (c >= 'a' && c <= 'z') ||
    (c >= 'A' && c <= 'Z') ||
    (c >= '0' && c <= '9') ||
    c == '_' ||
    c == '-'
  })
